# ---------------------------------------------------------------------------
# Logo / icoon (document met regels, staalblauw) - zelfde stijl als DraveForms
# ---------------------------------------------------------------------------
def make_logo(size=32, solid_bg=False):
    pm = QPixmap(size, size)
    pm.fill(QColor(BG) if solid_bg else Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    s = size
    m = s * 0.16
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QBrush(QColor(ACCENT)))
    p.drawRoundedRect(int(m), int(m * 0.7), int(s - 2 * m), int(s - 1.4 * m),
                      int(s * 0.10), int(s * 0.10))
    p.setPen(QPen(QColor(BG), max(1, int(s * 0.05))))
    widths = (0.68, 0.68, 0.52)
    for i in range(3):
        yy = int(s * 0.36 + i * s * 0.16)
        p.drawLine(int(s * 0.30), yy, int(s * widths[i]), yy)
    p.end()
    return pm


def app_icon():
    # Dravenlock-huislogo (draak) als het naast/bij de app staat; anders getekend.
    dirs = [_app_dir()]
    mp = getattr(sys, "_MEIPASS", None)
    if mp:
        dirs.append(mp)
    dirs.append(os.path.join(_app_dir(), "_internal"))
    for d in dirs:
        for name in ("logo.ico", "logo.png"):
            p = os.path.join(d, name)
            if os.path.exists(p):
                ic = QIcon(p)
                if not ic.isNull():
                    return ic
    return QIcon(make_logo(64))


