# PWA-bouwstenen
# ---------------------------------------------------------------------------
SW_JS = """const CACHE = 'draveedit-v1';
const ASSETS = ['./', './index.html', './icons/icon-192.png', './icons/icon-512.png'];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)));
  self.skipWaiting();
});
self.addEventListener('activate', e => { e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', e => {
  e.respondWith(caches.match(e.request).then(r => r || fetch(e.request)));
});
"""


def manifest_json(name):
    data = {
        "name": name,
        "short_name": name[:12],
        "start_url": ".",
        "display": "standalone",
        "background_color": "#ffffff",
        "theme_color": BG,
        "icons": [
            {"src": "icons/icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "icons/icon-512.png", "sizes": "512x512", "type": "image/png",
             "purpose": "any maskable"},
        ],
    }
    return json.dumps(data, ensure_ascii=False, indent=2)


def inject_pwa(doc):
    head = ('  <link rel="manifest" href="manifest.json">\n'
            '  <meta name="theme-color" content="%s">\n' % BG)
    if "</head>" in doc:
        doc = doc.replace("</head>", head + "</head>", 1)
    reg = ('<script>if("serviceWorker" in navigator){'
           'window.addEventListener("load",function(){'
           'navigator.serviceWorker.register("sw.js");});}</script>\n')
    if "</body>" in doc:
        doc = doc.replace("</body>", reg + "</body>", 1)
    return doc


# ---------------------------------------------------------------------------
# Brug: JavaScript -> Python
# ---------------------------------------------------------------------------
class Bridge(QObject):
    def __init__(self, win):
        super().__init__()
        self.win = win

    @pyqtSlot(bool)
    def setDirty(self, d):
        self.win.set_dirty(d)

    @pyqtSlot()
    def welcomeSeen(self):
        try:
            self.win.cfg["welcome_seen"] = True
            save_config(self.win.cfg)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Pagina: link-clicks naar buiten openen (in de echte browser)
# ---------------------------------------------------------------------------
class EditorPage(QWebEnginePage):
    def acceptNavigationRequest(self, url, nav_type, is_main_frame):
        if nav_type == QWebEnginePage.NavigationType.NavigationTypeLinkClicked:
            host = url.host()
            if host and host != "draveedit.local":
                QDesktopServices.openUrl(url)
            # binnen de app nooit "wegnavigeren" op een link
            return False
        return super().acceptNavigationRequest(url, nav_type, is_main_frame)


# ---------------------------------------------------------------------------
# Hoofdvenster
# ---------------------------------------------------------------------------
class MainWindow(QMainWindow):
    def __init__(self, cfg):
        super().__init__()
        self.cfg = cfg
        self.path = None
        self._dirty = False

        self.setWindowTitle(APP_NAME)
        self.setWindowIcon(app_icon())
        self.resize(1280, 860)

        self.view = QWebEngineView()
        self.view.setPage(EditorPage(self.view))
        self.setCentralWidget(self.view)

        self.channel = QWebChannel()
        self.bridge = Bridge(self)
        self.channel.registerObject("bridge", self.bridge)
        self.view.page().setWebChannel(self.channel)
        self._zoom = float(self.cfg.get("zoom", 1.0) or 1.0)
        self.view.loadFinished.connect(self._on_loaded)
        self.view.setHtml(EDITOR_HTML, QUrl("https://draveedit.local/"))

        self._toolbar = None
        self._applang = self._effective_lang()
        self._build_menu()
        self._apply_style()
        try:
            QApplication.styleHints().colorSchemeChanged.connect(
                self._on_os_scheme_changed)
        except Exception:
            pass

    # ---- taal (volgt computer, of handmatig) ----
    def _detect_os_lang(self):
        try:
            loc = QLocale.system().name().lower()
            return "nl" if loc.startswith("nl") else "en"
        except Exception:
            return "nl"

    def _effective_lang(self):
        l = (self.cfg.get("lang") or "").lower()
        if l in ("nl", "en"):
            return l
        return self._detect_os_lang()

    def _t(self, s):
        if getattr(self, "_applang", "nl") == "en":
            return TR_PY["en"].get(s, s)
        return s

    def _rebuild_menus(self):
        self.menuBar().clear()
        if getattr(self, "_toolbar", None) is not None:
            self.removeToolBar(self._toolbar)
            self._toolbar = None
        self._build_menu()

    def set_applang(self, code):
        self.cfg["lang"] = code  # "auto"/""  -> volgt computer; "nl"/"en" vast
        save_config(self.cfg)
        self._applang = self._effective_lang()
        self._rebuild_menus()
        try:
            self.view.page().runJavaScript("DE.setLang(%s)" % json.dumps(self._applang))
        except Exception:
            pass
        self._toast(self._t("Taal: %s") % ({"nl": self._t("Nederlands"),
                    "en": self._t("Engels")}.get(self._applang, self._applang)))

    # ---- UI ----
    def _act(self, text, slot, shortcut=None, tip=None):
        a = QAction(text, self)
        a.triggered.connect(slot)
        if shortcut:
            a.setShortcut(QKeySequence(shortcut))
        if tip:
            a.setStatusTip(tip)
        return a

    def _on_loaded(self, ok):
        # toegankelijkheid: bewaarde tekstgrootte (zoom) + hoog contrast toepassen
        try:
            self.view.setZoomFactor(self._zoom)
        except Exception:
            pass
        if self.cfg.get("contrast"):
            self.view.page().runJavaScript("DE.setContrast(true)")
        try:
            self.view.page().runJavaScript(
                "DE.setScheme(%s)" % json.dumps(self._effective_scheme()))
        except Exception:
            pass
        try:
            self.view.page().runJavaScript(
                "DE.setLang(%s)" % json.dumps(self._effective_lang()))
        except Exception:
            pass
        if not self.cfg.get("welcome_seen"):
            try:
                self.view.page().runJavaScript("DE.showWelcome()")
            except Exception:
                pass

    def _toast(self, msg):
        try:
            self.view.page().runJavaScript("DE.toast(%s)" % json.dumps(msg))
        except Exception:
            pass

    def toggle_contrast(self, on):
        self.cfg["contrast"] = bool(on)
        save_config(self.cfg)
        self.view.page().runJavaScript(
            "DE.setContrast(%s)" % ("true" if on else "false"))
        self._toast(self._t("Hoog contrast: %s") % (self._t("aan") if on else self._t("uit")))

    def set_zoom(self, factor):
        self._zoom = max(0.8, min(2.2, round(float(factor), 2)))
        try:
            self.view.setZoomFactor(self._zoom)
        except Exception:
            pass
        self.cfg["zoom"] = self._zoom
        save_config(self.cfg)
        self._toast(self._t("Tekstgrootte: %d%%") % round(self._zoom * 100))

    def zoom_step(self, delta):
        self.set_zoom(self._zoom + delta)

    def _build_menu(self):
        T = self._t
        mb = self.menuBar()
        m_file = mb.addMenu(T("&Bestand"))
        m_file.addAction(self._act(T("Nieuw (leeg)"), self.new_doc, "Ctrl+N"))
        m_tpl = m_file.addMenu(T("Nieuw van sjabloon"))
        for label, key in [(T("Landingspagina"), "landing"), (T("Over mij"), "overmij"),
                           (T("Contactpagina"), "contact"), (T("Leeg"), "leeg")]:
            m_tpl.addAction(self._act(label, lambda _=False, k=key: self.new_from_template(k)))
        m_file.addAction(self._act(T("Openen\u2026"), self.open_doc, "Ctrl+O"))
        m_file.addSeparator()
        m_file.addAction(self._act(T("Opslaan"), self.save_doc, "Ctrl+S"))
        m_file.addAction(self._act(T("Opslaan als\u2026"), self.save_doc_as, "Ctrl+Shift+S"))
        m_file.addSeparator()
        m_file.addAction(self._act(T("Voorbeeld in browser\u2026"), self.preview_in_browser, "Ctrl+P"))
        m_file.addAction(self._act(T("Exporteer als 1 HTML-bestand\u2026"), self.export_html))
        m_file.addAction(self._act(T("Exporteer website-zip (HTML + CSS + PWA)\u2026"), self.export_site_zip))
        m_file.addAction(self._act(T("Exporteer naar map (HTML + CSS + PWA)\u2026"), self.export_site_folder))
        m_file.addSeparator()
        m_file.addAction(self._act(T("Afsluiten"), self.close, "Ctrl+Q"))

        m_view = mb.addMenu(T("&Beeld"))
        m_view.addAction(self._act(T("Grotere tekst"), lambda: self.zoom_step(0.1), "Ctrl+="))
        m_view.addAction(self._act(T("Kleinere tekst"), lambda: self.zoom_step(-0.1), "Ctrl+-"))
        m_view.addAction(self._act(T("Normale grootte"), lambda: self.set_zoom(1.0), "Ctrl+0"))
        m_view.addSeparator()
        self.act_contrast = QAction(T("Hoog contrast"), self, checkable=True)
        self.act_contrast.setChecked(bool(self.cfg.get("contrast")))
        self.act_contrast.toggled.connect(self.toggle_contrast)
        m_view.addAction(self.act_contrast)
        m_view.addSeparator()
        m_theme = m_view.addMenu(T("Thema"))
        grp = QActionGroup(self)
        grp.setExclusive(True)
        cur = self.cfg.get("thememode", "auto")
        for mode, label in [("auto", T("Automatisch (Windows)")),
                            ("light", T("Licht")), ("dark", T("Donker"))]:
            a = QAction(label, self, checkable=True)
            a.setChecked(mode == cur)
            a.triggered.connect(lambda _=False, m=mode: self.set_thememode(m))
            grp.addAction(a)
            m_theme.addAction(a)
        m_lang = m_view.addMenu(T("Taal"))
        glg = QActionGroup(self)
        glg.setExclusive(True)
        curl = (self.cfg.get("lang") or "auto")
        for code, label in [("auto", T("Automatisch (computer)")),
                            ("nl", "Nederlands"), ("en", "English")]:
            a = QAction(label, self, checkable=True)
            a.setChecked(code == curl or (code == "auto" and curl not in ("nl", "en")))
            a.triggered.connect(lambda _=False, c=code: self.set_applang(c))
            glg.addAction(a)
            m_lang.addAction(a)
        m_view.addSeparator()
        m_view.addAction(self._act(T("Toegankelijkheid controleren"), self.check_a11y))

        m_help = mb.addMenu(T("&Help"))
        m_help.addAction(self._act(T("Snelgids"), self.show_guide))
        m_help.addAction(self._act(T("Over"), self.show_about))
        m_help.addAction(self._act(T("Donatie"), lambda: QDesktopServices.openUrl(QUrl(DONATE_URL))))

        # Snelle toolbar
        tb = self.addToolBar("Hoofd")
        self._toolbar = tb
        tb.setMovable(False)
        for text, slot in [(T("Nieuw"), self.new_doc), (T("Openen"), self.open_doc),
                           (T("Opslaan"), self.save_doc),
                           (T("In browser"), self.preview_in_browser),
                           (T("Website-zip"), self.export_site_zip)]:
            tb.addAction(self._act(text, slot))
        tb.addSeparator()
        tb.addAction(self._act("A\u2212", lambda: self.zoom_step(-0.1),
                               tip=T("Tekst kleiner")))
        tb.addAction(self._act("A+", lambda: self.zoom_step(0.1),
                               tip=T("Tekst groter (toegankelijkheid)")))
        tb.addAction(self.act_contrast)

    def _build_status(self):
        sb = QStatusBar()
        self.setStatusBar(sb)
        sb.addWidget(QLabel("  " + APP_NAME + "  "))
        sb.addPermanentWidget(QLabel("v" + APP_VERSION))
        donate = QToolButton()
        donate.setText("\u2665 Donatie")
        donate.setStyleSheet("color:%s;border:none;background:transparent" % ACCENT)
        donate.clicked.connect(lambda: QDesktopServices.openUrl(QUrl(DONATE_URL)))
        sb.addPermanentWidget(donate)

    def _apply_style(self, scheme=None):
        if scheme is None:
            scheme = self._effective_scheme()
        if scheme == "light":
            c = {"panel": "#ffffff", "silver": "#1b1d24", "line": "#dadde4",
                 "line2": "#c3c7d1", "accent": "#2563aa", "mute": "#54596a",
                 "onacc": "#ffffff", "tbbg": "#eef0f4"}
        else:
            c = {"panel": PANEL, "silver": SILVER, "line": LINE, "line2": LINE2,
                 "accent": ACCENT, "mute": MUTE, "onacc": "#08131f", "tbbg": "#1b1b21"}
        self.setStyleSheet("""
            QMainWindow, QMenuBar, QToolBar, QStatusBar { background: %(panel)s; color: %(silver)s; }
            QMenuBar { border-bottom: 1px solid %(line)s; }
            QMenuBar::item { padding: 6px 11px; background: transparent; }
            QMenuBar::item:selected { background: %(line2)s; border-radius: 6px; }
            QMenu { background: %(panel)s; color: %(silver)s; border: 1px solid %(line2)s; padding: 4px; }
            QMenu::item { padding: 7px 32px 7px 16px; border-radius: 6px; }
            QMenu::item:selected { background: %(accent)s; color: %(onacc)s; }
            QMenu::item:disabled { color: %(mute)s; }
            QMenu::indicator:checked { width: 13px; height: 13px; }
            QMenu::separator { height: 1px; background: %(line)s; margin: 5px 10px; }
            QMenu::right-arrow { width: 11px; height: 11px; margin-right: 8px; }
            QToolBar { border-bottom: 1px solid %(line)s; spacing: 4px; padding: 4px 6px; }
            QToolButton { color: %(silver)s; padding: 6px 11px; border: 1px solid %(line2)s;
                          border-radius: 8px; background: %(tbbg)s; }
            QToolButton:hover { border-color: %(accent)s; }
            QStatusBar { border-top: 1px solid %(line)s; color: %(mute)s; }
            QLabel { color: %(mute)s; }
        """ % c)

    # ---- thema (volgt Windows licht/donker, of handmatig) ----
    def _detect_os_scheme(self):
        try:
            cs = QApplication.styleHints().colorScheme()
            if cs == Qt.ColorScheme.Light:
                return "light"
            if cs == Qt.ColorScheme.Dark:
                return "dark"
        except Exception:
            pass
        try:
            import winreg
            k = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
            v, _ = winreg.QueryValueEx(k, "AppsUseLightTheme")
            return "light" if v else "dark"
        except Exception:
            pass
        return "dark"

    def _effective_scheme(self):
        mode = self.cfg.get("thememode", "auto")
        if mode in ("light", "dark"):
            return mode
        return self._detect_os_scheme()

    def apply_scheme(self):
        s = self._effective_scheme()
        self._apply_style(s)
        try:
            self.view.page().runJavaScript("DE.setScheme(%s)" % json.dumps(s))
        except Exception:
            pass

    def set_thememode(self, mode):
        self.cfg["thememode"] = mode
        save_config(self.cfg)
        self.apply_scheme()
        labels = {"auto": self._t("Automatisch (Windows)"), "light": self._t("Licht"), "dark": self._t("Donker")}
        self._toast(self._t("Thema: %s") % labels.get(mode, mode))

    def _on_os_scheme_changed(self, *args):
        if self.cfg.get("thememode", "auto") == "auto":
            self.apply_scheme()

    # ---- dirty / titel ----
    def set_dirty(self, d):
        self._dirty = bool(d)
        self._update_title()

    def _update_title(self):
        name = os.path.basename(self.path) if self.path else "Naamloos"
        mark = "*" if self._dirty else ""
        self.setWindowTitle("%s \u2014 %s%s" % (APP_NAME, name, mark))

    def _maybe_discard(self):
        """Vraagt om opslaan bij niet-bewaarde wijzigingen. True = doorgaan."""
        if not self._dirty:
            return True
        r = QMessageBox.question(
            self, self._t("Niet-opgeslagen wijzigingen"),
            self._t("Wil je de wijzigingen opslaan?"),
            QMessageBox.StandardButton.Save | QMessageBox.StandardButton.Discard
            | QMessageBox.StandardButton.Cancel)
        if r == QMessageBox.StandardButton.Save:
            self.save_doc()
            return True
        if r == QMessageBox.StandardButton.Cancel:
            return False
        return True

    # ---- acties ----
    def new_doc(self):
        if not self._maybe_discard():
            return
        self.path = None
        self.view.page().runJavaScript("DE.newDoc()")
        self._update_title()

    def new_from_template(self, key):
        if not self._maybe_discard():
            return
        self.path = None
        self.view.page().runJavaScript("DE.loadTemplate(%s)" % json.dumps(key))
        self._update_title()

    def preview_in_browser(self):
        self.view.page().runJavaScript("DE.getExportParts()", self._do_preview)

    def _do_preview(self, parts_json):
        import tempfile
        try:
            d = tempfile.mkdtemp(prefix="draveedit_preview_")
            for rel, data in self._site_files("Voorbeeld", parts_json or "{}").items():
                dest = os.path.join(d, *rel.split("/"))
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with open(dest, "wb") as f:
                    f.write(data)
            port = self._serve_dir(d)
            # http-adres -> opent altijd de standaardbrowser (niet de .html-editor)
            QDesktopServices.openUrl(QUrl("http://127.0.0.1:%d/index.html" % port))
        except Exception as e:
            QMessageBox.warning(self, "Kon voorbeeld niet openen", str(e))

    def _serve_dir(self, directory):
        """Start een klein, stil, multi-thread webservertje en geef de poort."""
        import http.server
        import functools
        import threading

        class _QuietHandler(http.server.SimpleHTTPRequestHandler):
            # pythonw heeft geen stderr -> standaard-logging zou crashen
            def log_message(self, *a, **k):
                pass

        handler = functools.partial(_QuietHandler, directory=directory)
        httpd = http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler)
        httpd.daemon_threads = True
        httpd.handle_error = lambda request, client_address: None
        port = httpd.server_address[1]
        threading.Thread(target=httpd.serve_forever, daemon=True).start()
        if not hasattr(self, "_preview_servers"):
            self._preview_servers = []
        self._preview_servers.append(httpd)
        return port

    def check_a11y(self):
        self.view.page().runJavaScript("DE.checkA11y()")

    def open_doc(self):
        if not self._maybe_discard():
            return
        path, _ = QFileDialog.getOpenFileName(
            self, "Project openen", "",
            "DraveEdit-project (*.dehtml *.html);;Alle bestanden (*)")
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                html = f.read()
        except Exception as e:
            QMessageBox.warning(self, "Kon niet openen", str(e))
            return
        self.view.page().runJavaScript("DE.loadProjectHTML(%s)" % json.dumps(html))
        self.path = path
        self.set_dirty(False)

    def save_doc(self):
        if not self.path:
            return self.save_doc_as()
        self.view.page().runJavaScript(
            "DE.getProjectHTML()",
            lambda h: self._write_project(self.path, h or ""))

    def save_doc_as(self):
        path, _ = QFileDialog.getSaveFileName(
            self, "Project opslaan", self.path or "mijn-project.dehtml",
            "DraveEdit-project (*.dehtml)")
        if not path:
            return
        if not path.lower().endswith(".dehtml"):
            path += ".dehtml"
        self.path = path
        self.view.page().runJavaScript(
            "DE.getProjectHTML()",
            lambda h: self._write_project(path, h or ""))

    def _write_project(self, path, html):
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(html)
            self.set_dirty(False)
            self._update_title()
            self._toast("Opgeslagen: %s" % os.path.basename(path))
        except Exception as e:
            QMessageBox.warning(self, "Kon niet opslaan", str(e))

    def export_html(self):
        path, _ = QFileDialog.getSaveFileName(
            self, "Exporteer als 1 HTML-bestand", "index.html", "HTML (*.html)")
        if not path:
            return
        if not path.lower().endswith(".html"):
            path += ".html"
        self.view.page().runJavaScript(
            "DE.getExportDoc()",
            lambda doc: self._write_text(path, doc or "",
                                         "index.html geexporteerd"))

    def _write_text(self, path, text, msg):
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
            self._toast(msg)
        except Exception as e:
            QMessageBox.warning(self, "Kon niet exporteren", str(e))

    def _parts(self, parts_json):
        try:
            d = json.loads(parts_json or "{}")
        except Exception:
            d = {}
        return d.get("html", ""), d.get("css", "")

    def _site_files(self, name, parts_json):
        """Alles in een keer: HTML + CSS + PWA-bestanden, als {pad: bytes}."""
        html, css = self._parts(parts_json)
        files = {}
        files["index.html"] = inject_pwa(html).encode("utf-8")
        files["css/index_style.css"] = css.encode("utf-8")
        files["manifest.json"] = manifest_json(name).encode("utf-8")
        files["sw.js"] = SW_JS.encode("utf-8")
        from PyQt6.QtCore import QBuffer, QByteArray
        for sz in (192, 512):
            ba = QByteArray()
            buf = QBuffer(ba)
            buf.open(QBuffer.OpenModeFlag.WriteOnly)
            make_logo(sz, solid_bg=True).toImage().save(buf, "PNG")
            files["icons/icon-%d.png" % sz] = bytes(ba)
        return files

    def export_site_zip(self):
        path, _ = QFileDialog.getSaveFileName(
            self, "Exporteer website-zip (HTML + CSS + PWA)",
            "mijn-website.zip", "Zip (*.zip)")
        if not path:
            return
        if not path.lower().endswith(".zip"):
            path += ".zip"
        self.view.page().runJavaScript(
            "DE.getExportParts()",
            lambda parts: self._build_site_zip(path, parts or "{}"))

    def _build_site_zip(self, path, parts_json):
        import zipfile
        try:
            name = os.path.splitext(os.path.basename(path))[0] or "Mijn website"
            with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
                for rel, data in self._site_files(name, parts_json).items():
                    z.writestr(rel, data)
            QMessageBox.information(
                self, "Website-zip klaar",
                "Opgeslagen:\n%s\n\nAlles zit erin: index.html, css/index_style.css, "
                "manifest.json, sw.js en icons/.\nPak uit op een HTTPS-adres (of "
                "localhost) om als PWA te kunnen installeren." % path)
        except Exception as e:
            QMessageBox.warning(self, "Kon zip niet maken", str(e))

    def export_site_folder(self):
        folder = QFileDialog.getExistingDirectory(
            self, "Kies een (lege) map voor de website")
        if not folder:
            return
        self.view.page().runJavaScript(
            "DE.getExportParts()",
            lambda parts: self._build_site_folder(folder, parts or "{}"))

    def _build_site_folder(self, folder, parts_json):
        try:
            name = os.path.basename(folder.rstrip("/\\")) or "Mijn website"
            for rel, data in self._site_files(name, parts_json).items():
                dest = os.path.join(folder, *rel.split("/"))
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with open(dest, "wb") as f:
                    f.write(data)
            QMessageBox.information(
                self, "Website geexporteerd",
                "Klaar in:\n%s\n\nAlles zit erin (HTML + CSS + PWA). Zet de map op "
                "een HTTPS-adres (of localhost) om als PWA te installeren." % folder)
        except Exception as e:
            QMessageBox.warning(self, "Kon niet exporteren", str(e))

    def show_guide(self):
        self.view.page().runJavaScript(
            "document.getElementById('helpBtn') && document.getElementById('helpBtn').click()")

    def show_about(self):
        if self._applang == "en":
            body = ("%s v%s\n\nWYSIWYG HTML5 editor with live preview and PWA export.\n"
                    "Dravenlock\n%s\n%s" % (APP_NAME, APP_VERSION, SUPPORT_MAIL, DONATE_URL))
        else:
            body = ("%s v%s\n\nWYSIWYG HTML5-editor met live preview en PWA-export.\n"
                    "Dravenlock\n%s\n%s" % (APP_NAME, APP_VERSION, SUPPORT_MAIL, DONATE_URL))
        QMessageBox.information(self, self._t("Over"), body)

    def closeEvent(self, ev):
        if self._maybe_discard():
            for httpd in getattr(self, "_preview_servers", []):
                try:
                    httpd.shutdown()
                except Exception:
                    pass
            ev.accept()
        else:
            ev.ignore()


def _install_excepthook():
    import traceback

    def hook(exctype, value, tb):
        msg = "".join(traceback.format_exception(exctype, value, tb))
        try:
            with open(os.path.join(_app_dir(), "draveedit-fout.txt"),
                      "w", encoding="utf-8") as f:
                f.write(msg)
        except Exception:
            pass
        try:
            if QApplication.instance():
                QMessageBox.critical(None, "DraveEdit - fout",
                                     "Er ging iets mis:\n\n" + msg[-1500:]
                                     + "\n\n(Ook opgeslagen in draveedit-fout.txt)")
        except Exception:
            pass
        sys.__excepthook__(exctype, value, tb)

    sys.excepthook = hook


def main():
    _install_excepthook()
    # Sommige Windows-GPU's geven witte vlakken in QtWebEngine; software-
    # compositing voorkomt dat. (Iets trager, maar betrouwbaar.)
    os.environ.setdefault("QTWEBENGINE_CHROMIUM_FLAGS",
                          "--disable-gpu --disable-gpu-compositing")
    QCoreApplication.setAttribute(
        Qt.ApplicationAttribute.AA_ShareOpenGLContexts)
    app = QApplication(sys.argv)
    try:
        cfg = load_config()
        win = MainWindow(cfg)
        win.show()
    except Exception:
        sys.excepthook(*sys.exc_info())
        return
    try:  # Dravenlock: stille update-check (uit te zetten; Ctrl+Shift+U = met de hand)
        import drave_update
        drave_update.start(win, 'DraveEdit', APP_VERSION)
    except Exception:
        pass
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
